}
.newsletter p { color: var(--muted); margin: 0 0 20px; line-height: 1.6; }
.newsletter-form {
  display: flex;
  gap: 8px;
  background: var(--bg-2);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 6px;
  max-width: 460px;
}
.newsletter-form input {
  flex: 1;
  background: transparent;
  border: none;
