  color: var(--accent);
  line-height: 1;
}
.perk .l { font-size: 13px; color: var(--text); font-weight: 600; }
.perk .d { font-size: 12px; color: var(--muted); line-height: 1.5; }

/* Footer */
.site-footer {
  background: var(--bg-1);
  border-top: 1px solid var(--line);
  padding-top: 64px;
}
.footer-inner {
  max-width: 1280px;
  margin: 0 auto;
  padding: 0 24px 32px;
  display: grid;
  grid-template-columns: 1.5fr repeat(4, 1fr);
  gap: 48px;
}
.footer-brand .brand { margin-bottom: 16px; }
.footer-brand p { color: var(--muted); font-size: 14px; line-height: 1.6; max-width: 320px; }
.socials {
  display: flex;
  gap: 8px;
  margin-top: 20px;
}
.socials a {
  width: 36px; height: 36px;
  border-radius: 10px;
  background: var(--bg-2);
  border: 1px solid var(--line);
  color: var(--muted);
  display: grid; place-items: center;
  transition: color 0.15s, border-color 0.15s, background 0.15s;
}
.socials a:hover { color: var(--accent); border-color: var(--accent); background: var(--bg-3); }
.socials svg { width: 16px; height: 16px; }

.footer-col h4 {
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.14em;
  color: var(--text);
  margin: 0 0 16px;
  font-weight: 600;
}
.footer-col ul { list-style: none; padding: 0; margin: 0; display: flex; flex-direction: column; gap: 10px; }
.footer-col a { color: var(--muted); font-size: 14px; }
.footer-col a:hover { color: var(--text); }

.footer-bottom {
  border-top: 1px solid var(--line);
  padding: 22px 24px;
  max-width: 1280px;
  margin: 0 auto;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 12px;
  color: var(--dim);
  flex-wrap: wrap;
  gap: 16px;
}
.footer-bottom .pay {
  display: flex;
  gap: 8px;
}
.footer-bottom .pay span {
  background: var(--bg-2);
  border: 1px solid var(--line);
  padding: 4px 10px;
  border-radius: 6px;
  font-size: 11px;
  font-weight: 600;
  color: var(--muted);
  letter-spacing: 0.04em;
}

/* Responsive */
@media (max-width: 1024px) {
  .product-grid { grid-template-columns: repeat(3, 1fr); }
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .editorial-grid .story-1 { grid-column: span 2; }
  .footer-inner { grid-template-columns: 1fr 1fr 1fr; }
  .footer-brand { grid-column: span 3; }
  .deals-grid { grid-template-columns: 1fr 1fr; }
  .deal-1 { grid-row: auto; grid-column: span 2; min-height: 320px; }
}
@media (max-width: 768px) {
