  .nav { display: none; }
  .announce-links { display: none; }
  .hero-grid { grid-template-columns: 1fr; gap: 40px; padding: 48px 20px 64px; }
  .hero-stats { gap: 24px; }
  .section { padding: 64px 20px; }
  .section-head { flex-direction: column; align-items: flex-start; gap: 16px; }
  .product-grid { grid-template-columns: repeat(2, 1fr); gap: 14px; }
  .deals-grid { grid-template-columns: 1fr; }
  .deal-1, .deal-1 h3 { grid-column: auto; }
  .deal-1 { min-height: 260px; }
  .deal-1 h3 { font-size: 32px; }
  .editorial-grid { grid-template-columns: 1fr; }
  .editorial-grid .story-1 { grid-column: auto; }
  .trust-grid { grid-template-columns: 1fr 1fr; }
  .newsletter-inner { grid-template-columns: 1fr; padding: 56px 20px; }
  .footer-inner { grid-template-columns: 1fr 1fr; }
  .footer-brand { grid-column: span 2; }
  .footer-bottom { flex-direction: column; align-items: flex-start; }
}
@media (max-width: 480px) {
  .product-info { padding: 12px 14px 14px; }
  .price-now { font-size: 15px; }
  .add-btn { padding: 7px 10px; font-size: 11px; }
}
