+  --radius: 14px;
+  --radius-sm: 8px;
+  --shadow: 0 10px 40px rgba(0, 0, 0, 0.45);
+  --font: "Inter", "Segoe UI", system-ui, -apple-system, sans-serif;
+  --serif: "Cormorant Garamond", "Playfair Display", Georgia, serif;
+}
+
+* { box-sizing: border-box; }
+
+html, body {
+  margin: 0;
+  padding: 0;
+  background: var(--bg-0);
+  color: var(--text);
+  font-family: var(--font);
+  -webkit-font-smoothing: antialiased;
+  text-rendering: optimizeLegibility;
+}
+
+a { color: inherit; text-decoration: none; }
+button { font: inherit; cursor: pointer; }
+img { max-width: 100%; display: block; }
+
+:focus-visible {
+  outline: 2px solid var(--accent);
+  outline-offset: 2px;
+  border-radius: 4px;
+}
+
+.skip-link {
+  position: absolute;
+  left: -9999px;
+  top: 0;
+  background: var(--accent);
+  color: var(--accent-ink);
+  padding: 10px 16px;
+  font-weight: 600;
+  z-index: 999;
+}
+.skip-link:focus { left: 12px; top: 12px; }
+
+.sr-only {
+  position: absolute;
+  width: 1px; height: 1px;
+  padding: 0; margin: -1px;
+  overflow: hidden; clip: rect(0,0,0,0);
+  white-space: nowrap; border: 0;
+}
+
+/* Announcement bar */
+.announce {
+  background: var(--bg-1);
+  border-bottom: 1px solid var(--line);
+  font-size: 13px;
+  color: var(--muted);
+}
+.announce-inner {
+  max-width: 1280px;
+  margin: 0 auto;
+  padding: 10px 24px;
+  display: flex;
+  justify-content: space-between;
+  align-items: center;
+  gap: 16px;
+}
+.announce-msg { display: flex; align-items: center; gap: 8px; }
+.announce-msg strong { color: var(--text); }
+.announce-links { display: flex; gap: 18px; }
+.announce-links a:hover { color: var(--text); }
+
+/* Header */
+.site-header {
+  position: sticky;
+  top: 0;
+  z-index: 50;
+  background: rgba(10, 10, 12, 0.85);
+  backdrop-filter: blur(14px);
+  -webkit-backdrop-filter: blur(14px);
+  border-bottom: 1px solid var(--line);
+}
+.header-inner {
+  max-width: 1280px;
+  margin: 0 auto;
+  padding: 16px 24px;
+  display: grid;
+  grid-template-columns: 1fr auto 1fr;
+  align-items: center;
+  gap: 24px;
+}
+.brand {
+  font-family: var(--serif);
+  font-weight: 600;
+  font-size: 26px;
+  letter-spacing: 0.5px;
+  display: flex;
+  align-items: center;
+  gap: 10px;
+}
+.brand-mark {
+  width: 28px; height: 28px;
+  background: var(--accent);
+  color: var(--accent-ink);
+  display: grid; place-items: center;
+  border-radius: 6px;
+  font-family: var(--font);
+  font-weight: 800;
+  font-size: 14px;
+}
+.nav {
+  display: flex;
+  justify-content: center;
+  gap: 28px;
+}
+.nav a {
+  font-size: 14px;
+  font-weight: 500;
+  color: var(--muted);
+  padding: 6px 2px;
+  position: relative;
+  transition: color 0.15s ease;
+}
+.nav a:hover, .nav a[aria-current="page"] { color: var(--text); }
+.nav a[aria-current="page"]::after {
+  content: "";
+  position: absolute;
+  left: 0; right: 0; bottom: -2px;
+  height: 2px;
+  background: var(--accent);
+  border-radius: 2px;
+}
+.header-actions {
+  display: flex;
+  justify-content: flex-end;
+  align-items: center;
+  gap: 6px;
+}
+.icon-btn {
+  background: transparent;
+  border: 1px solid transparent;
+  color: var(--muted);
+  width: 40px; height: 40px;
+  border-radius: 10px;
+  display: grid; place-items: center;
+  position: relative;
+  transition: background 0.15s, color 0.15s, border-color 0.15s;
+}
+.icon-btn:hover { background: var(--bg-2); color: var(--text); border-color: var(--line); }
+.icon-btn svg { width: 20px; height: 20px; }
+.cart-badge {
+  position: absolute;
+  top: 4px; right: 4px;
+  background: var(--accent);
+  color: var(--accent-ink);
+  font-size: 10px;
+  font-weight: 700;
+  min-width: 16px; height: 16px;
+  border-radius: 8px;
+  padding: 0 4px;
+  display: grid; place-items: center;
+}
+
+/* Hero */
+.hero {
+  position: relative;
+  overflow: hidden;
+  border-bottom: 1px solid var(--line);
+}
+.hero-grid {
+  max-width: 1280px;
+  margin: 0 auto;
+  padding: 80px 24px 96px;
+  display: grid;
+  grid-template-columns: 1.1fr 1fr;
+  gap: 64px;
+  align-items: center;
+}
+.hero-eyebrow {
+  display: inline-flex;
+  align-items: center;
+  gap: 8px;
+  background: var(--bg-2);
+  border: 1px solid var(--line);
+  border-radius: 999px;
+  padding: 6px 14px;
+  font-size: 12px;
+  letter-spacing: 0.12em;
+  text-transform: uppercase;
+  color: var(--muted);
+}
+.hero-eyebrow .dot {
+  width: 6px; height: 6px;
+  border-radius: 50%;
+  background: var(--accent);
+  box-shadow: 0 0 0 4px rgba(212, 255, 58, 0.15);
+}
+.hero h1 {
+  font-family: var(--serif);
+  font-weight: 500;
+  font-size: clamp(44px, 6vw, 80px);
+  line-height: 1.02;
+  letter-spacing: -0.02em;
+  margin: 20px 0 20px;
+}
+.hero h1 em {
+  font-style: italic;
+  color: var(--accent);
+}
+.hero p.lead {
+  color: var(--muted);
+  font-size: 17px;
+  line-height: 1.6;
+  max-width: 480px;
+  margin: 0 0 32px;
+}
+.hero-cta { display: flex; gap: 12px; flex-wrap: wrap; }
+.btn {
+  display: inline-flex;
+  align-items: center;
+  gap: 8px;
+  padding: 14px 22px;
+  border-radius: 999px;
+  font-size: 14px;
+  font-weight: 600;
+  border: 1px solid transparent;
+  transition: transform 0.1s ease, background 0.15s, border-color 0.15s, color 0.15s;
+}
+.btn:active { transform: translateY(1px); }
+.btn-primary { background: var(--accent); color: var(--accent-ink); }
+.btn-primary:hover { background: #e3ff66; }
+.btn-ghost { background: transparent; color: var(--text); border-color: var(--line-2); }
+.btn-ghost:hover { background: var(--bg-2); border-color: var(--line-2); }
+.btn svg { width: 16px; height: 16px; }
+
+.hero-stats {
+  display: flex;
+  gap: 36px;
+  margin-top: 48px;
+  padding-top: 32px;
+  border-top: 1px solid var(--line);
+}
+.hero-stats div .num {
+  font-family: var(--serif);
+  font-size: 28px;
+  color: var(--text);
+  display: block;
+  line-height: 1;
+}
+.hero-stats div .lbl {
+  font-size: 12px;
+  color: var(--dim);
+  text-transform: uppercase;
+  letter-spacing: 0.1em;
+  margin-top: 6px;
+  display: block;
+}
+
+.hero-visual {
+  position: relative;
+  aspect-ratio: 4/5;
+  border-radius: 24px;
+  overflow: hidden;
+  background: linear-gradient(135deg, #1a1a22, #0c0c10);
+  border: 1px solid var(--line);
+  box-shadow: var(--shadow);
+}
+.hero-visual::before {
+  content: "";
+  position: absolute;
+  inset: 0;
+  background:
+    radial-gradient(60% 50% at 70% 20%, rgba(212, 255, 58, 0.18), transparent 60%),
+    radial-gradient(40% 40% at 20% 80%, rgba(120, 100, 255, 0.18), transparent 60%);
+}
+.hero-product {
+  position: absolute;
+  inset: 0;
+  display: grid; place-items: center;
+}
+.hero-product .silhouette {
+  width: 70%;
+  height: 80%;
+  background:
+    radial-gradient(ellipse at 50% 40%, rgba(255,255,255,0.06), transparent 70%),
+    linear-gradient(180deg, #2a2a35 0%, #15151c 100%);
+  border-radius: 50% 50% 45% 45% / 60% 60% 40% 40%;
+  filter: blur(0.5px);
+  box-shadow: inset 0 -40px 80px rgba(0,0,0,0.6), inset 0 40px 80px rgba(255,255,255,0.04);
+}
+.hero-tag {
+  position: absolute;
+  background: rgba(17, 17, 20, 0.85);
+  backdrop-filter: blur(8px);
+  border: 1px solid var(--line-2);
+  border-radius: 12px;
+  padding: 12px 14px;
+  font-size: 13px;
+  display: flex;
+  align-items: center;
+  gap: 10px;
+  box-shadow: var(--shadow);
+}
+.hero-tag .swatch {
+  width: 28px; height: 28px; border-radius: 8px;
+  background: linear-gradient(135deg, #d4ff3a, #87a700);
+}
+.hero-tag-1 { top: 24px; left: 24px; }
+.hero-tag-2 { bottom: 24px; right: 24px; }
+.hero-tag .price { font-weight: 700; color: var(--text); }
+.hero-tag .label { color: var(--muted); font-size: 11px; text-transform: uppercase; letter-spacing: 0.08em; }
+
+/* Section heading */
+.section {
+  max-width: 1280px;
+  margin: 0 auto;
+  padding: 88px 24px;
+}
+.section-head {
+  display: flex;
+  align-items: flex-end;
+  justify-content: space-between;
+  gap: 24px;
+  margin-bottom: 40px;
+}
+.section-head .titles {
+  flex: 1;
+}
+.section-eyebrow {
+  font-size: 12px;
+  letter-spacing: 0.16em;
+  text-transform: uppercase;
+  color: var(--accent);
+  font-weight: 600;
+}
+.section-head h2 {
+  font-family: var(--serif);
+  font-weight: 500;
+  font-size: clamp(32px, 4vw, 48px);
+  letter-spacing: -0.01em;
+  margin: 8px 0 0;
+  line-height: 1.1;
+}
+.section-head .sub {
+  color: var(--muted);
+  margin-top: 12px;
+  max-width: 560px;
+  line-height: 1.6;
+}
+.section-head .view-all {
+  font-size: 14px;
+  color: var(--muted);
+  display: inline-flex;
+  align-items: center;
+  gap: 6px;
+  border-bottom: 1px solid var(--line-2);
+  padding-bottom: 4px;
+}
+.section-head .view-all:hover { color: var(--accent); border-color: var(--accent); }
+
+/* Category chips */
+.chip-row {
+  display: flex;
+  gap: 10px;
+  flex-wrap: wrap;
+  margin-bottom: 32px;
+}
+.chip {
+  background: var(--bg-2);
+  border: 1px solid var(--line);
+  color: var(--muted);
+  padding: 9px 16px;
+  border-radius: 999px;
+  font-size: 13px;
+  font-weight: 500;
+  transition: background 0.15s, color 0.15s, border-color 0.15s;
+}
+.chip:hover { color: var(--text); border-color: var(--line-2); }
+.chip[aria-pressed="true"] {
+  background: var(--text);
+  color: var(--accent-ink);
+  border-color: var(--text);
+}
+
+/* Product grid */
+.product-grid {
+  display: grid;
+  grid-template-columns: repeat(4, 1fr);
+  gap: 24px;
+}
+.product {
+  background: var(--bg-1);
+  border: 1px solid var(--line);
+  border-radius: var(--radius);
+  overflow: hidden;
+  transition: transform 0.2s ease, border-color 0.2s ease;
+  display: flex;
+  flex-direction: column;
+}
+.product:hover {
+  transform: translateY(-4px);
+  border-color: var(--line-2);
+}
+.product-media {
+  position: relative;
+  aspect-ratio: 1 / 1;
+  background: var(--bg-2);
+  overflow: hidden;
+}
+.product-media .art {
+  position: absolute; inset: 0;
+  display: grid; place-items: center;
+  font-family: var(--serif);
+  font-size: 80px;
+  color: rgba(255,255,255,0.06);
+}
+.product-media::after {
+  content: "";
+  position: absolute;
+  inset: 0;
+  background: radial-gradient(120% 80% at 50% 0%, rgba(255,255,255,0.05), transparent 60%);
+  pointer-events: none;
+}
+.product-badges {
+  position: absolute;
+  top: 12px; left: 12px;
+  display: flex;
+  flex-direction: column;
+  gap: 6px;
+}
+.badge {
+  font-size: 11px;
+  font-weight: 700;
+  letter-spacing: 0.06em;
+  text-transform: uppercase;
+  padding: 5px 9px;
+  border-radius: 6px;
+  background: var(--bg-3);
+  color: var(--text);
+  border: 1px solid var(--line-2);
+}
+.badge.new { background: var(--accent); color: var(--accent-ink); border-color: var(--accent); }
+.badge.sale { background: var(--danger); color: white; border-color: var(--danger); }
+.badge.low { background: var(--warn); color: var(--accent-ink); border-color: var(--warn); }
+
+.wishlist-btn {
+  position: absolute;
+  top: 12px; right: 12px;
+  background: rgba(17, 17, 20, 0.7);
+  backdrop-filter: blur(6px);
+  border: 1px solid var(--line);
+  color: var(--muted);
+  width: 36px; height: 36px;
+  border-radius: 50%;
+  display: grid; place-items: center;
+  transition: color 0.15s, background 0.15s;
+}
+.wishlist-btn:hover { color: var(--accent); }
+.wishlist-btn[aria-pressed="true"] { color: var(--danger); background: rgba(255, 91, 91, 0.12); border-color: rgba(255,91,91,0.3); }
+.wishlist-btn svg { width: 18px; height: 18px; }
+
+.product-info {
+  padding: 16px 18px 18px;
+  display: flex;
+  flex-direction: column;
+  gap: 10px;
+  flex: 1;
+}
+.product-cat {
+  font-size: 11px;
+  text-transform: uppercase;
+  letter-spacing: 0.1em;
+  color: var(--dim);
+}
+.product-name {
+  font-size: 15px;
+  font-weight: 600;
+  margin: 0;
+  line-height: 1.3;
+}
+.product-rating {
+  display: flex;
+  align-items: center;
+  gap: 6px;
+  font-size: 12px;
+  color: var(--muted);
+}
+.stars { color: var(--accent); letter-spacing: 1px; }
+.product-bottom {
+  margin-top: auto;
+  padding-top: 8px;
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 12px;
+}
+.price-block { display: flex; align-items: baseline; gap: 8px; }
+.price-now { font-size: 17px; font-weight: 700; }
+.price-was { font-size: 13px; color: var(--dim); text-decoration: line-through; }
+.add-btn {
+  background: var(--bg-3);
+  color: var(--text);
+  border: 1px solid var(--line-2);
+  padding: 8px 14px;
+  border-radius: 999px;
+  font-size: 12px;
+  font-weight: 600;
+  transition: background 0.15s, color 0.15s;
+}
+.add-btn:hover { background: var(--accent); color: var(--accent-ink); border-color: var(--accent); }
+
+/* Deals strip */
+.deals-band {
+  background: linear-gradient(180deg, var(--bg-1), var(--bg-0));
+  border-top: 1px solid var(--line);
+  border-bottom: 1px solid var(--line);
+}
+.deals-grid {
+  display: grid;
+  grid-template-columns: 1.4fr 1fr 1fr;
+  gap: 20px;
+}
+.deal {
+  position: relative;
+  border-radius: var(--radius);
+  overflow: hidden;
+  border: 1px solid var(--line);
+  padding: 32px;
+  min-height: 280px;
+  display: flex;
+  flex-direction: column;
+  justify-content: space-between;
+  transition: border-color 0.2s ease;
+}
+.deal:hover { border-color: var(--line-2); }
+.deal-1 {
+  grid-row: span 2;
+  background:
+    radial-gradient(80% 60% at 80% 100%, rgba(212, 255, 58, 0.18), transparent 60%),
+    linear-gradient(160deg, #1d1f17 0%, #0d0d0a 100%);
+  min-height: 580px;
+}
+.deal-2 {
+  background:
+    radial-gradient(80% 80% at 100% 0%, rgba(120, 100, 255, 0.18), transparent 60%),
+    linear-gradient(160deg, #161522 0%, #0c0c14 100%);
+}
+.deal-3 {
+  background:
+    radial-gradient(80% 80% at 0% 100%, rgba(255, 120, 200, 0.16), transparent 60%),
+    linear-gradient(160deg, #1f141a 0%, #100b0e 100%);
+}
+.deal-tag {
+  display: inline-flex;
+  align-items: center;
+  gap: 6px;
+  font-size: 11px;
+  letter-spacing: 0.14em;
+  text-transform: uppercase;
+  color: var(--muted);
+  font-weight: 600;
+}
+.deal-tag .pill {
+  background: var(--accent);
+  color: var(--accent-ink);
+  padding: 3px 8px;
+  border-radius: 4px;
+  letter-spacing: 0.08em;
+}
+.deal h3 {
+  font-family: var(--serif);
+  font-weight: 500;
+  font-size: 28px;
+  line-height: 1.15;
+  margin: 14px 0 8px;
+  letter-spacing: -0.01em;
+}
+.deal-1 h3 { font-size: 44px; max-width: 460px; }
+.deal-desc { color: var(--muted); font-size: 14px; line-height: 1.55; max-width: 380px; }
+.deal-foot {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  margin-top: 24px;
+  gap: 16px;
+}
+.deal-link {
+  font-size: 14px;
+  font-weight: 600;
+  display: inline-flex;
+  align-items: center;
+  gap: 8px;
+  color: var(--text);
+  border-bottom: 1px solid var(--line-2);
+  padding-bottom: 4px;
+}
+.deal-link:hover { color: var(--accent); border-color: var(--accent); }
+
+/* Countdown */
+.countdown {
+  display: flex;
+  gap: 8px;
+  margin-top: 20px;
+}
+.cd-cell {
+  background: rgba(0,0,0,0.3);
+  border: 1px solid var(--line);
+  border-radius: 8px;
+  padding: 10px 12px;
+  text-align: center;
+  min-width: 56px;
+}
+.cd-cell .v {
+  font-family: var(--serif);
+  font-size: 24px;
+  font-weight: 600;
+  display: block;
+  line-height: 1;
+  font-variant-numeric: tabular-nums;
+}
+.cd-cell .l {
+  font-size: 10px;
+  color: var(--dim);
+  letter-spacing: 0.1em;
+  text-transform: uppercase;
+  margin-top: 4px;
+  display: block;
+}
+
+/* Editorial */
+.editorial-grid {
+  display: grid;
+  grid-template-columns: 2fr 1fr 1fr;
+  gap: 24px;
+}
+.story {
+  border: 1px solid var(--line);
+  background: var(--bg-1);
+  border-radius: var(--radius);
+  overflow: hidden;
+  display: flex;
+  flex-direction: column;
+  transition: border-color 0.2s, transform 0.2s;
+}
+.story:hover { border-color: var(--line-2); transform: translateY(-4px); }
+.story-media {
+  aspect-ratio: 4/3;
+  position: relative;
+  background: var(--bg-2);
+  overflow: hidden;
+}
+.story-1 .story-media {
+  aspect-ratio: 16/10;
+  background:
+    radial-gradient(60% 60% at 30% 30%, rgba(212, 255, 58, 0.2), transparent 60%),
+    linear-gradient(135deg, #1c1f15, #0e0f0a);
+}
+.story-2 .story-media {
+  background:
+    radial-gradient(60% 60% at 70% 30%, rgba(120, 100, 255, 0.18), transparent 60%),
+    linear-gradient(135deg, #16162b, #0a0a14);
+}
+.story-3 .story-media {
+  background:
+    radial-gradient(60% 60% at 50% 50%, rgba(255, 120, 200, 0.16), transparent 60%),
+    linear-gradient(135deg, #1f141a, #100a0d);
+}
+.story-media .art {
+  position: absolute; inset: 0;
+  display: grid; place-items: center;
+  font-family: var(--serif);
+  font-size: 120px;
+  color: rgba(255,255,255,0.05);
+  font-style: italic;
+}
+.story-body {
+  padding: 22px 24px 26px;
+  display: flex;
+  flex-direction: column;
+  gap: 10px;
+  flex: 1;
+}
+.story-meta {
+  font-size: 11px;
+  color: var(--accent);
+  text-transform: uppercase;
+  letter-spacing: 0.14em;
+  font-weight: 600;
+  display: flex;
+  align-items: center;
+  gap: 10px;
+}
+.story-meta .dot { color: var(--dim); }
+.story-meta .read { color: var(--muted); font-weight: 500; letter-spacing: 0.08em; }
+.story-1 h3 {
+  font-family: var(--serif);
+  font-weight: 500;
+  font-size: 30px;
+  line-height: 1.15;
+  margin: 0;
+  letter-spacing: -0.01em;
+}
+.story h3 {
+  font-family: var(--serif);
+  font-weight: 500;
+  font-size: 22px;
+  line-height: 1.2;
+  margin: 0;
+  letter-spacing: -0.01em;
+}
+.story p {
+  color: var(--muted);
+  font-size: 14px;
+  line-height: 1.55;
+  margin: 0;
+}
+.story-foot {
+  margin-top: auto;
+  padding-top: 12px;
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  font-size: 13px;
+  color: var(--muted);
+}
+.author { display: flex; align-items: center; gap: 10px; }
+.avatar {
+  width: 28px; height: 28px;
+  border-radius: 50%;
+  background: linear-gradient(135deg, var(--accent), #5d7000);
+  color: var(--accent-ink);
