const Newsletter = () => {
  const [email, setEmail] = useState("");
  const [status, setStatus] = useState("");
  const submit = (ev) => {
    ev.preventDefault();
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
      setStatus("Please enter a valid email address.");
      return;
    }
    setStatus(`Thanks — we've added ${email} to the list.`);
    setEmail("");
  };
  return (
    <section className="newsletter" aria-labelledby="news-title">
      <div className="newsletter-inner">
        <div>
          <span className="section-eyebrow">Maison Membership</span>
          <h2 id="news-title">Letters from the studio.</h2>
          <p>Monthly dispatches on new releases, restocks, and behind-the-scenes from our ateliers. No noise.</p>
          <form className="newsletter-form" onSubmit={submit} noValidate aria-describedby="news-help">
            <label className="sr-only" htmlFor="news-email">Email address</label>
            <input
              id="news-email"
              type="email"
              autoComplete="email"
              placeholder="your@email.com"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
            />
            <button type="submit">Subscribe</button>
          </form>
          <p id="news-help" className="small">By subscribing you agree to our privacy policy. Unsubscribe anytime.</p>
          <p className="newsletter-status" role="status" aria-live="polite">{status}</p>
        </div>
        <aside className="newsletter-side" aria-label="Member benefits">
          <div className="perk">
            <span className="num">48h</span>
            <span className="l">Early access</span>
            <span className="d">Shop new drops before everyone else.</span>
          </div>
          <div className="perk">
            <span className="num">5%</span>
            <span className="l">Welcome credit</span>
            <span className="d">On your first order over $200.</span>
          </div>
          <div className="perk">
            <span className="num">∞</span>
            <span className="l">Free repairs</span>
            <span className="d">Lifetime mending on every garment.</span>
          </div>
          <div className="perk">
            <span className="num">240k</span>
            <span className="l">Members</span>
            <span className="d">A growing community in 38 countries.</span>
          </div>
        </aside>
